// Typed access to the synthetic demo data generated by data/scripts/generate.mjs.
import raw from './demoData.json';
import { C, themed } from '../theme';

export type Driver = { key: string; label: string; z: number; from: number; to: number; change: string };
export type Series = Record<string, (number | null)[]>;
export type Person = { name: string; role: string; series: Series; drivers: Driver[][]; questionnaires: { day: number; date: string; who5: number; phq9?: number }[] };
export type NightPoint = { time: string; stage: 'awake' | 'light' | 'deep' | 'rem'; hr: number };
type Demo = {
  generatedFrom: string; days: number; startDate: string;
  events: { relapseStart: number; firstAlertDay: number; firstHighDay: number; carePlanDay: number; recoveredDay: number };
  people: Record<string, Person>;
  samNights: { day30: NightPoint[]; day66: NightPoint[] };
  samDayHr: { day30: number[]; day66: number[] };
  population: { sleepH: number; rhr: number; steps: number; depressedMorningRatio: number; depressedActivityRatio: number };
  clinic: { patient: string; weeksSinceTms: number; risk: number | null; level: string; drivers: string[]; lastCheckIn: string }[];
};
export const DEMO = raw as unknown as Demo;
export const SAM = DEMO.people.sam;

export type Level = 'calibrating' | 'steady' | 'watch' | 'high';
export const levelOf = (risk: number | null | undefined): Level => (risk == null ? 'calibrating' : risk >= 55 ? 'high' : risk >= 30 ? 'watch' : 'steady');
export const LEVEL_UI: Record<Level, { label: string; color: string; bg: string; text: string }> = themed(() => ({
  calibrating: { label: 'Learning your normal', color: C.muted, bg: C.night3, text: 'Mellow is still learning what a normal week looks like for you.' },
  steady: { label: 'Steady', color: C.forest, bg: C.greenSoft, text: 'Everything is within your usual range.' },
  watch: { label: 'Worth watching', color: C.amber, bg: C.amberSoft, text: 'A few things have shifted from your usual pattern. Nothing urgent, just worth noticing.' },
  high: { label: 'Check in', color: C.rose, bg: C.roseSoft, text: 'Several signals match your early warning signs. Mellow suggests reaching out, with your permission.' },
}));

export function dateOfDay(day: number) {
  const d = new Date(DEMO.startDate + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + day - 1);
  return d;
}
export const fmtDay = (day: number) => dateOfDay(day).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
export const weekdayLetter = (day: number) => 'SMTWTFS'[dateOfDay(day).getUTCDay()];

// Values for the n days ending on `day` (1-based).
export function windowOf(arr: (number | null)[], day: number, n = 14) {
  const end = Math.max(n, day);
  return arr.slice(end - n, end);
}
export function meanOf(a: (number | null)[]) { const v = a.filter((x): x is number => x != null); return v.length ? v.reduce((s, x) => s + x, 0) / v.length : null; }
// Personal baseline: days 7..34, before anything changed.
export function baseline(key: string) { return meanOf(SAM.series[key].slice(6, 34)); }

// ---------- whose data Journey shows ----------
// The demo shows Sam. A signed-in person with their own daily data sees theirs, on the same 90-day calendar
// (day 1 = DEMO.startDate), with their usual worked out from their first 4 weeks, like the care portal does.
export type JourneyData = { series: Series; drivers: Driver[][]; baseline: (key: string) => number | null; own: boolean };
export const DEMO_PERSON: JourneyData = { series: SAM.series, drivers: SAM.drivers, baseline, own: false };
type Row = { day: string; reasons: { key: string; label: string; change?: string; z?: number }[] | null; [col: string]: unknown };
const COLS: [string, string][] = [
  ['sleepHours', 'sleep_hours'], ['steps', 'steps'], ['morningSteps', 'morning_steps'], ['screenMinutes', 'screen_minutes'],
  ['lateNightScreenMinutes', 'late_night_screen_minutes'], ['restingHr', 'resting_hr'], ['hrvRmssd', 'hrv_rmssd'],
  ['messagesSent', 'messages_sent'], ['mood', 'mood'], ['risk', 'risk'],
];
export function personFromRows(rows: Row[]): JourneyData | null {
  const start = Date.parse(DEMO.startDate + 'T00:00:00Z');
  const series: Series = Object.fromEntries(COLS.map(([k]) => [k, Array(DEMO.days).fill(null)]));
  const reasons: Row['reasons'][] = Array(DEMO.days).fill(null);
  const seen: number[] = [];
  for (const r of rows) {
    const d = Math.round((Date.parse(r.day + 'T00:00:00Z') - start) / 864e5) + 1;
    if (d < 1 || d > DEMO.days) continue;
    seen.push(d);
    for (const [k, col] of COLS) { const v = r[col]; series[k][d - 1] = typeof v === 'number' ? v : null; }
    reasons[d - 1] = r.reasons;
  }
  if (!seen.length || series.risk.every((v) => v == null)) return null; // nothing to show yet: keep the demo
  const first = Math.min(...seen);
  const usual = (key: string) => (series[key] ? meanOf(series[key].slice(first - 1, first - 1 + 28)) : null);
  // The care portal stores each day's reasons; turn them into "was X, now Y" so Journey can describe the direction.
  const drivers: Driver[][] = reasons.map((list, i) => (list || []).map((x) => {
    const to = meanOf(windowOf(series[x.key] || [], i + 1, 7)), from = usual(x.key);
    return { key: x.key, label: x.label, z: x.z ?? 0, from: from ?? 0, to: to ?? 0, change: x.change ?? '' };
  }));
  return { series, drivers, baseline: usual, own: true };
}
